import openpyxl

wb = openpyxl.load_workbook('output.xlsx')
ws = wb['Sheet1']

# risk table rows 4-9: A=ID, B=Impact, C=Likelihood
data = {}
for r in range(4, 10):
    rid = ws.cell(row=r, column=1).value
    imp = ws.cell(row=r, column=2).value
    lik = ws.cell(row=r, column=3).value
    if rid is not None:
        data[rid] = (imp, lik)

print(data)

# Map box cell to (impact, likelihood)
# F12:H14 ; row12->imp3, row13->imp2, row14->imp1 ; colF->lik1, colG->lik2, colH->lik3
box_imp = {12:3, 13:2, 14:1}
box_lik = {6:1, 7:2, 8:3}

result = {}
for row, imp in box_imp.items():
    for col, lik in box_lik.items():
        ids = [str(k) for k,v in data.items() if v[0]==imp and v[1]==lik]
        result[(row,col)] = ", ".join(ids)

print(result)

for (row,col), val in result.items():
    ws.cell(row=row, column=col).value = val

wb.save('output.xlsx')
print("saved")
EOF
python3 solve.py
